// Validate on this side too.
//
// AURA already validated against the manifest's JSON Schema before the
// request left the machine. This is the second check, and it exists
// because the webhook URL is reachable by anything that can route to
// n8n -- not only by AURA.

const args = $input.first().json.body ?? {};
const channel = String(args.channel || '').trim();
const text = String(args.text || '').trim();

if (!channel || !text) {
  throw new Error('channel and text are both required');
}
if (text.length > 4000) {
  throw new Error('text is too long');
}

return [{ json: { channel, text } }];

// ===================================================================
// REPLACE THIS NODE with the real destination.
//
// Drag in Slack (Send Message), Discord, Telegram or Mattermost, wire
// it here, and map channel/text onto its fields. Its credentials live
// in n8n and never reach AURA -- that is the entire arrangement.
//
// Until you do, this workflow is a dry run: it reports what it WOULD
// have sent and sends nothing.
// ===================================================================

const { channel, text } = $input.first().json;

return [{
  json: {
    summary: `DRY RUN -- would post to #${channel}: "${text}"`,
    sent: false,
    channel,
    text
  }
}];
